import re
from collections import Counter

def most_frequent_word(message):
    words = re.findall(r'[a-z]+', message.lower())
    if not words:
        return ''
    counts = Counter(words)
    best = max(counts.values())
    for w in words:
        if counts[w] == best:
            return w
    return ''

