import re

def most_frequent_word(message):
    words = re.findall(r'[a-z]+', message.lower())
    if not words:
        return ''
    best, chosen = -1, ''
    for w in words:
        c = sum(1 for x in words if x == w)
        if c > best:
            best, chosen = c, w
    return chosen
